{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "10",
      "explanation": "The SOQL query is constructed by concatenating user input, which can lead to SOQL injection if the input is not properly sanitized.",
      "remediation": "Use bind variables or String.escapeSingleQuotes to safely include user input in the query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions elements",
      "explanation": "The permission set grants excessive permissions such as ModifyAllData and ViewAllData, which are not necessary for the described purpose of supporting tier-1 agents.",
      "remediation": "Remove unnecessary permissions such as ModifyAllData and ViewAllData from the permission set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Insecure sharing model in ContactSearchController",
      "severity": "Medium",
      "file": "ContactSearchController.cls",
      "lines": "2-8",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing settings and can expose data to users who should not have access.",
      "remediation": "Change the class declaration to 'with sharing' or 'inherited sharing' to enforce sharing settings."
    },
    {
      "category": "C5",
      "title": "Guest user profile allows access to ContactSearchController",
      "severity": "Medium",
      "file": "Partner Site Profile.profile-meta.xml",
      "lines": "5-19",
      "explanation": "The Guest User License profile allows access to the ContactSearchController class, which can expose sensitive contact data to unauthenticated users.",
      "remediation": "Remove the classAccess to ContactSearchController from the Guest User License profile or ensure the class enforces strict sharing and field-level security."
    }
  ]
}
